import React from 'react';

export default function BookCard({ book, actionType, onAction }) {
  const avail = book.availableCopies > 0;

  return (
    <div className="book-card" style={{ display: 'flex', flexDirection: 'column' }}>
      <div style={{
        background: 'linear-gradient(145deg,rgba(245,225,160,0.15),rgba(100,80,140,0.2))',
        padding: '1.5rem 1rem 1rem', textAlign: 'center',
        borderBottom: '1px solid rgba(255,215,0,0.25)'
      }}>
        {book.imageBase64
          ? <img src={book.imageBase64} alt={book.title} style={{ width:64,height:64,objectFit:'cover',borderRadius:'0.75rem',margin:'0 auto 0.75rem',display:'block',border:'2px solid rgba(255,255,255,0.2)' }} />
          : <div style={{ fontSize:'3.5rem', marginBottom:'0.75rem' }}>📘</div>
        }
        <div style={{ fontWeight:700, fontSize:'0.9rem', lineHeight:1.3, color:'#FFF9E8', marginBottom:'0.25rem', overflow:'hidden', display:'-webkit-box', WebkitLineClamp:2, WebkitBoxOrient:'vertical' }}>{book.title}</div>
        <div style={{ fontSize:'0.7rem', opacity:0.8, fontStyle:'italic', marginBottom:'0.5rem' }}>by {book.author}</div>
        <div style={{ background:'rgba(0,0,0,0.4)', borderRadius:'2rem', padding:'0.2rem 0.6rem', fontSize:'0.7rem', fontWeight:600, display:'inline-block' }}>
          {book.availableCopies}/{book.totalCopies} copies
        </div>
      </div>

      <div style={{ padding: '0.75rem' }}>
        {actionType === 'manage' && (
          <div style={{ display:'flex', gap:'0.5rem' }}>
            <button onClick={() => onAction('edit', book)} className="btn-ghost" style={{ flex:1, padding:'0.5rem', fontSize:'0.75rem', textAlign:'center' }}>✏️ EDIT</button>
            <button onClick={() => onAction('delete', book)} style={{ flex:1, padding:'0.5rem', fontSize:'0.75rem', background:'rgba(239,68,68,0.4)', borderRadius:'0.75rem', border:'none', color:'white', cursor:'pointer', fontWeight:600 }}>🗑️ DEL</button>
          </div>
        )}
        {actionType === 'issue' && (
          <button onClick={() => onAction('select-issue', book)} className="btn-ghost" style={{ width:'100%', padding:'0.5rem', fontSize:'0.75rem', textAlign:'center', opacity: avail ? 1 : 0.4 }} disabled={!avail}>
            SELECT TO ISSUE
          </button>
        )}
        {actionType === 'request' && (
          <button onClick={() => onAction('request', book)} className="btn-ghost" style={{ width:'100%', padding:'0.5rem', fontSize:'0.75rem', textAlign:'center', opacity: avail ? 1 : 0.4 }} disabled={!avail}>
            {avail ? '✉️ REQUEST' : 'OUT OF STOCK'}
          </button>
        )}
        {!actionType && (
          <span style={{ display:'block', textAlign:'center', padding:'0.4rem', fontSize:'0.75rem', borderRadius:'2rem', background: avail ? 'rgba(34,197,94,0.4)' : 'rgba(239,68,68,0.4)', fontWeight:600 }}>
            {avail ? 'AVAILABLE' : 'OUT OF STOCK'}
          </span>
        )}
      </div>
    </div>
  );
}
